public class BankAccount {
    private double balance;

    public BankAccount(double balance) {
        this.balance = balance;
    }

    public void deposit(double amount) {
        if (amount > 0) {
            balance += amount;
        }
    }

    public void withdraw(double amount) {
        if (amount > 0 && amount <= balance) {
            balance -= amount;
        }
    }

    public double getBalance() {
        return balance;
    }
}

testcode.text:
BankAccount a = new BankAccount(100.0);
a.deposit(20.0);
a.withdraw(50.0);
System.out.print(a.getBalance());

BankAccount a = new BankAccount(40.0);
a.withdraw(60.0);
a.deposit(-5.0);
System.out.print(a.getBalance());

question.answer:
abstract class Shape {
    public abstract double area();
}

class Rectangle extends Shape {
    private double width;
    private double height;

    public Rectangle(double width, double height) {
        this.width = width;
        this.height = height;
    }

    @Override
    public double area() {
        return width * height;
    }
}

public class Circle extends Shape {
    private double radius;

    public Circle(double radius) {
        this.radius = radius;
    }

    @Override
    public double area() {
        return Math.PI * radius * radius;
    }
}

testcode.text:
Shape r = new Rectangle(3, 4);
Shape c = new Circle(1);
System.out.println(r.area());
System.out.print(String.format("%.2f", c.area()));

question.answer:
public class Team {
    private java.util.ArrayList<String> members;

    public Team() {
        members = new java.util.ArrayList<String>();
    }

    public void addMember(String name) {
        if (name != null && !name.isEmpty()) {
            members.add(name);
        }
    }

    public int getMemberCount() {
        return members.size();
    }
}

testcode.text:
Team t = new Team();
t.addMember("Ali");
t.addMember("Bo");
System.out.print(t.getMemberCount());

Team t = new Team();
t.addMember("");
t.addMember(null);
System.out.print(t.getMemberCount());
